<?php
session_start();
header("X-Frame-Options: DENY");
if(!isset($_SESSION['user_id']) || !isset($_SESSION['login_time'])){ header('Location: login.php'); exit; }
if(time() - $_SESSION['login_time'] > 3600){ session_destroy(); header('Location: login.php'); exit; }
$_SESSION['login_time']=time();
$id=intval($_GET['id']??0);
$data=json_decode(file_get_contents(__DIR__.'/fake_db.json'),true);
if($_SERVER['REQUEST_METHOD']=='POST' && ($_SESSION['role']??'')=='admin'){
  foreach($data['complaints'] as &$c){ if($c['id']==$id){ $c['status']=htmlspecialchars($_POST['new_status']); $c['admin_response']=htmlspecialchars($_POST['history_comment']); break; } }
  file_put_contents(__DIR__.'/fake_db.json',json_encode($data,JSON_PRETTY_PRINT));
  header('Location: complaint_details.php?id='.$id.'&saved=1'); exit;
}
$c=null; foreach($data['complaints'] as $x){ if($x['id']==$id){ $c=$x; break; } }
if(!$c){ header('Location: dashboard.php'); exit; }
$isOwner = $c['user_id']==$_SESSION['user_id'] || ($_SESSION['role']??'')=='admin';
if(!$isOwner){ header('Location: dashboard.php'); exit; }
?>
