o strtolower($c['status'])=='pending'?'b-pend':'b-close'; ?>"><?php echo htmlspecialchars($c['status']); ?></span><span class="badge" style="background:#eef2ff;color:#4338ca"><?php echo htmlspecialchars($c['category']); ?></span><span style="font-size:11px;color:#6b7280">ID: <?php echo $c['id']; ?> • User: <?php echo htmlspecialchars($c['user_name']); ?> (<?php echo $c['user_id']; ?>)</span></div><div style="margin-top:14px;font-weight:800;font-size:18px"><?php echo htmlspecialchars($c['subject']); ?></div><div style="margin-top:8px;font-size:12px;color:#6b7280">📍 <?php echo htmlspecialchars($c['location']); ?> • 📅 <?php echo htmlspecialchars($c['created_at']); ?></div><div style="margin-top:16px;background:#f9fafb;border:1px solid #f3f4f6;padding:14px;border-radius:12px;font-size:13px;line-height:1.6"><?php echo nl2br(htmlspecialchars($c['description'])); ?></div><?php if(!empty($c['admin_response'])){ ?><div style="margin-top:14px;background:#f0fdf4;border:1px solid #bbf7d0;padding:14px;border-radius:12px"><div style="font-weight:700;font-size:12px;color:#166534">💬 Admin Response:</div><div style="font-size:13px;margin-top:6px"><?php echo htmlspecialchars($c['admin_response']); ?></div></div><?php } ?></div><?php if(($_SESSION['role']??'')=='admin'){ ?><div class="card"><div style="font-weight:800;font-size:14px">🔧 Update Status & Response (Admin Only)</div><form method="POST" style="margin-top:14px"><div style="display:grid;grid-template-columns:1fr 1fr;gap:12px"><div><label style="font-size:11px;font-weight:700">New Status</label><select name="new_status" style="width:100%;padding:10px;border:1.5px solid #eef0f6;border-radius:10px;margin-top:6px"><option <?php if($c['status']=='Pending') echo 'selected'; ?>>Pending</option><option>In Progress</option><option>Resolved</option><option>Closed</option></select></div><div><label style="font-size:11px;font-weight:700">Admin Comment</label><input name="history_comment" placeholder="e.g. Technician assigned" style="width:100%;padding:10px;border:1.5px solid #eef0f6;border-radius:10px;margin-top:6px" value="<?php echo htmlspecialchars($c['admin_response']); ?>"></div></div><button type="submit" style="margin-top:12px;padding:10px 18px;background:linear-gradient(135deg,#5a4cf1,#7c3aed);color:#fff;border:0;border-radius:10px;font-weight:700;cursor:pointer">💾 Save Changes</button></form></div><?php } ?></div></body></html>
